create table if not exists public.location_observations (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, observer_user_id uuid null references auth.users(id) on delete set null, observation_type text not null check (observation_type in ('discovered','encountered','arrived','community_observed','verified','business_claimed')), observed_at timestamptz not null default now(), latitude double precision, longitude double precision, accuracy_m double precision, evidence jsonb not null default '{}'::jsonb, confidence numeric check (confidence is null or confidence between 0 and 1), source text not null default 'app', expires_at timestamptz, created_at timestamptz not null default now()); create index if not exists idx_location_observations_location_time on public.location_observations(location_id,observed_at desc); create index if not exists idx_location_observations_user_time on public.location_observations(observer_user_id,observed_at desc); create index if not exists idx_location_observations_active on public.location_observations(location_id,observation_type,observed_at desc); alter table public.location_observations enable row level security; create policy location_observations_insert_own on public.location_observations for insert to authenticated with check (observer_user_id = auth.uid()); create policy location_observations_read_authenticated on public.location_observations for select to authenticated using (true); create or replace function public.record_location_observation(p_location_id uuid,p_observation_type text,p_latitude double precision default null,p_longitude double precision default null,p_accuracy_m double precision default null,p_evidence jsonb default '{}'::jsonb,p_confidence numeric default null,p_expires_at timestamptz default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; begin insert into public.location_observations(location_id,observer_user_id,observation_type,latitude,longitude,accuracy_m,evidence,confidence,expires_at) values(p_location_id,auth.uid(),p_observation_type,p_latitude,p_longitude,p_accuracy_m,coalesce(p_evidence,'{}'::jsonb),p_confidence,p_expires_at) returning id into v_id; return v_id; end; $$;
